@@ -0,0 +1,75 @@
+package main
+
+import (
+	"bytes"
+	"encoding/json"
+	"os"
+	"path/filepath"
+	"strings"
+	"testing"
+
+	"px1/internal/hosted/eval"
+)
+
+func writeResults2(t *testing.T, caught []bool) string {
+	t.Helper()
+	var results []eval.RunResult
+	for run, hit := range caught {
+		r := eval.RunResult{CaseID: "found", Run: run + 1}
+		if hit {
+			r.Findings = []eval.Finding{{Path: "src/refund.ts", StartLine: 3, EndLine: 3}}
+		}
+		results = append(results, r, eval.RunResult{CaseID: "never-found", Run: run + 1}, eval.RunResult{CaseID: "clean", Run: run + 1})
+	}
+	data, _ := json.Marshal(results)
+	path := filepath.Join(t.TempDir(), "results.json")
+	if err := os.WriteFile(path, data, 0o600); err != nil {
+		t.Fatal(err)
+	}
+	return path
+}
+
+func TestEvalCompareReportsRealAndNoiseDifferences(t *testing.T) {
+	cases := writeEvalCases(t, strings.Repeat("a", 40), strings.Repeat("b", 40))
+	before := writeResults2(t, []bool{false, false, false})
+	after := writeResults2(t, []bool{true, true, true})
+	out := filepath.Join(t.TempDir(), "cmp.md")
+	var stdout bytes.Buffer
+	if err := runEvalCompare([]string{"--cases", cases, "--before", before, "--after", after, "--out", out}, &stdout); err != nil {
+		t.Fatal(err)
+	}
+	for _, want := range []string{"| found | 0/3 | 3/3 |", "better", "| never-found | 0/3 | 0/3 |", "same"} {
+		if !strings.Contains(stdout.String(), want) {
+			t.Fatalf("missing %q:\n%s", want, stdout.String())
+		}
+	}
+	if saved, err := os.ReadFile(out); err != nil || string(saved) != stdout.String() {
+		t.Fatalf("saved report differs: %v", err)
+	}
+	// A one-run difference is noise.
+	var noise bytes.Buffer
+	if err := runEvalCompare([]string{"--cases", cases, "--before", writeResults2(t, []bool{true, true, false}), "--after", writeResults2(t, []bool{true, true, true})}, &noise); err != nil {
+		t.Fatal(err)
+	}
+	if !strings.Contains(noise.String(), "| found | 2/3 | 3/3 |") || strings.Contains(noise.String(), "| better |") {
+		t.Fatalf("a single extra find must not count as better:\n%s", noise.String())
+	}
+}
+
+func TestEvalCompareValidatesInput(t *testing.T) {
+	cases := writeEvalCases(t, strings.Repeat("a", 40), strings.Repeat("b", 40))
+	if err := runEvalCompare([]string{"--cases", cases}, &bytes.Buffer{}); err == nil {
+		t.Fatal("missing results must be rejected")
+	}
+	bad := filepath.Join(t.TempDir(), "bad.json")
+	os.WriteFile(bad, []byte("not json"), 0o600)
+	if err := runEvalCompare([]string{"--cases", cases, "--before", bad, "--after", bad}, &bytes.Buffer{}); err == nil {
+		t.Fatal("malformed results must be rejected")
+	}
+	unknown := writeResults2(t, []bool{true})
+	data, _ := os.ReadFile(unknown)
+	os.WriteFile(unknown, bytes.Replace(data, []byte(`"found"`), []byte(`"nope"`), 1), 0o600)
+	if err := runEvalCompare([]string{"--cases", cases, "--before", unknown, "--after", unknown}, &bytes.Buffer{}); err == nil {
+		t.Fatal("results for an unknown case must be rejected")
+	}
+}

diff --git a/internal/hosted/eval/compare.go b/internal/hosted/eval/compare.go
new file mode 100644
index 0000000..0ac8fe7
--- /dev/null
+++ b/internal/hosted/eval/compare.go
@@ -0,0 +1,154 @@
+package eval
+
+import (
+	"fmt"
+	"math"
+	"strings"
+)
+
+// A reviewer change is only worth keeping if it beats the noise. The same case
+// can be found in one run and missed in the next, so a before/after difference
+// of one run means nothing. CompareRepeat tests each labelled bug, and the
+// pooled result, with Fisher's exact test on found-versus-missed counts.
+
+// Significance is the two-sided p-value below which a difference is called real.
+// It is deliberately loose: with three runs a side the smallest possible p-value
+// is 0.1, and a stricter bar would call everything noise.
+const Significance = 0.10
+
+type LabelChange struct {
+	CaseID       string
+	Path         string
+	Line         int
+	BeforeCaught int
+	BeforeRuns   int
+	AfterCaught  int
+	AfterRuns    int
+	P            float64
+	Verdict      string // better, worse, or same
+}
+
+type Comparison struct {
+	Labels                    []LabelChange
+	Before, After             RepeatReport
+	PooledP                   float64
+	PooledVerdict             string
+	Improved, Regressed, Same int
+}
+
+// CompareRepeat compares two scored reports over the same dataset. Labels with
+// no scored run on either side are left out, since nothing can be said of them.
+func CompareRepeat(before, after RepeatReport) (Comparison, error) {
+	if len(before.Cases) != len(after.Cases) {
+		return Comparison{}, fmt.Errorf("reports cover different datasets (%d and %d cases)", len(before.Cases), len(after.Cases))
+	}
+	c := Comparison{Before: before, After: after}
+	var bc, bn, ac, an int
+	for i, b := range before.Cases {
+		a := after.Cases[i]
+		if a.ID != b.ID || len(a.Labels) != len(b.Labels) {
+			return Comparison{}, fmt.Errorf("case %d differs between reports (%q and %q)", i, b.ID, a.ID)
+		}
+		for j, bl := range b.Labels {
+			al := a.Labels[j]
+			if b.Runs == 0 || a.Runs == 0 {
+				continue
+			}
+			ch := LabelChange{CaseID: b.ID, Path: bl.Label.Path, Line: bl.Label.StartLine,
+				BeforeCaught: bl.Caught, BeforeRuns: b.Runs, AfterCaught: al.Caught, AfterRuns: a.Runs}
+			ch.P = fisherExact(bl.Caught, b.Runs-bl.Caught, al.Caught, a.Runs-al.Caught)
+			ch.Verdict = verdict(ch.P, rate(al.Caught, a.Runs)-rate(bl.Caught, b.Runs))
+			switch ch.Verdict {
+			case "better":
+				c.Improved++
+			case "worse":
+				c.Regressed++
+			default:
+				c.Same++
+			}
+			bc, bn, ac, an = bc+bl.Caught, bn+b.Runs, ac+al.Caught, an+a.Runs
+			c.Labels = append(c.Labels, ch)
+		}
+	}
+	if bn > 0 && an > 0 {
+		c.PooledP = fisherExact(bc, bn-bc, ac, an-ac)
+		c.PooledVerdict = verdict(c.PooledP, rate(ac, an)-rate(bc, bn))
+	}
+	return c, nil
+}
+
+func rate(n, total int) float64 {
+	if total == 0 {
+		return 0
+	}
+	return float64(n) / float64(total)
+}
+
+func verdict(p, delta float64) string {
+	switch {
+	case p > Significance || delta == 0:
+		return "same"
+	case delta > 0:
+		return "better"
+	default:
+		return "worse"
+	}
+}
+
+// fisherExact is the two-sided p-value for the table [[a b] [c d]]: the total
+// probability of tables, with the same margins, at most as likely as the one seen.
+func fisherExact(a, b, c, d int) float64 {
+	row1, row2, col1 := a+b, c+d, a+c
+	n := row1 + row2
+	if n == 0 {
+		return 1
+	}
+	prob := func(x int) float64 {
+		return math.Exp(logChoose(row1, x) + logChoose(row2, col1-x) - logChoose(n, col1))
+	}
+	observed := prob(a)
+	lo, hi := max(0, col1-row2), min(row1, col1)
+	p := 0.0
+	for x := lo; x <= hi; x++ {
+		if q := prob(x); q <= observed*(1+1e-9) {
+			p += q
+		}
+	}
+	return math.Min(1, p)
+}
+
+func logChoose(n, k int) float64 {
+	if k < 0 || k > n {
+		return math.Inf(-1)
+	}
+	a, _ := math.Lgamma(float64(n + 1))
+	b, _ := math.Lgamma(float64(k + 1))
+	c, _ := math.Lgamma(float64(n - k + 1))
+	return a - b - c
+}
+
+// Markdown renders the comparison. It leads with what cannot be concluded,
+// because most small before/after differences are noise.
+func (c Comparison) Markdown() string {
+	var b strings.Builder
+	b.WriteString("# Review comparison\n\n")
+	fmt.Fprintf(&b, "Before: %d scored runs, after: %d scored runs. A difference counts only at p ≤ %.2f (Fisher's exact test); with few runs most differences are noise.\n\n", c.Before.ScoredRuns, c.After.ScoredRuns, Significance)
+	fmt.Fprintf(&b, "| | Before | After |\n| --- | --- | --- |\n")
+	fmt.Fprintf(&b, "| Recall | %.0f%% | %.0f%% |\n", c.Before.Recall*100, c.After.Recall*100)
+	fmt.Fprintf(&b, "| Precision | %.0f%% | %.0f%% |\n", c.Before.Precision*100, c.After.Precision*100)
+	fmt.Fprintf(&b, "| Noise per clean run | %.2f | %.2f |\n", c.Before.NoisePerCleanRun, c.After.NoisePerCleanRun)
+	fmt.Fprintf(&b, "| Unstable bugs | %d | %d |\n", c.Before.FlakyLabels, c.After.FlakyLabels)
+	fmt.Fprintf(&b, "| Cost | $%.4f | $%.4f |\n\n", float64(c.Before.CostMicrousd)/1e6, float64(c.After.CostMicrousd)/1e6)
+	if c.PooledVerdict != "" {
+		fmt.Fprintf(&b, "**Overall: %s** (p=%.2f, pooled over all labelled bugs; runs of one bug are not fully independent, so treat this as a guide).\n\n", c.PooledVerdict, c.PooledP)
+	}
+	fmt.Fprintf(&b, "%d bugs clearly better, %d clearly worse, %d no clear difference.\n\n", c.Improved, c.Regressed, c.Same)
+	b.WriteString("| Case | Before | After | p | Verdict |\n| --- | --- | --- | --- | --- |\n")
+	for _, l := range c.Labels {
+		fmt.Fprintf(&b, "| %s | %d/%d | %d/%d | %.2f | %s |\n", l.CaseID, l.BeforeCaught, l.BeforeRuns, l.AfterCaught, l.AfterRuns, l.P, l.Verdict)
+	}
+	if c.After.NoisePerCleanRun > c.Before.NoisePerCleanRun {
+		b.WriteString("\n**Warning:** the after run flags more on clean changes: more findings may mean more false alarms, not a better reviewer.\n")
+	}
+	return b.String()
+}

diff --git a/internal/hosted/eval/compare_test.go b/internal/hosted/eval/compare_test.go
new file mode 100644
index 0000000..615c126
--- /dev/null
+++ b/internal/hosted/eval/compare_test.go
@@ -0,0 +1,99 @@
+package eval
+
+import (
+	"math"
+	"strings"
+	"testing"
+)
+
+func TestFisherExactKnownValues(t *testing.T) {
+	cases := []struct {
+		a, b, c, d int
+		want       float64
+	}{
+		{3, 0, 0, 3, 0.1}, // 3/3 against 0/3: the best a three-run test can show
+		{1, 2, 1, 2, 1},   // identical rates
+		{3, 0, 3, 0, 1},   // identical
+		{2, 1, 0, 3, 0.4}, // 2/3 against 0/3 is still noise
+		{10, 0, 0, 10, 1.08e-5},
+		{0, 0, 0, 0, 1},
+	}
+	for _, c := range cases {
+		got := fisherExact(c.a, c.b, c.c, c.d)
+		if math.Abs(got-c.want) > math.Max(1e-9, c.want*0.01) {
+			t.Errorf("fisherExact(%d,%d,%d,%d) = %v, want %v", c.a, c.b, c.c, c.d, got, c.want)
+		}
+	}
+}
+
+func reportFor(caught []int, runs int, noise float64) RepeatReport {
+	var r RepeatReport
+	r.NoisePerCleanRun = noise
+	for i, n := range caught {
+		r.Cases = append(r.Cases, CaseScore{ID: string(rune('a' + i)), Kind: "seeded", Runs: runs,
+			Labels: []LabelScore{{Label: Label{Path: "f.ts", StartLine: i + 1, EndLine: i + 1}, Caught: n}}})
+		r.ScoredRuns += runs
+	}
+	return r
+}
+
+func TestCompareRepeatCallsOnlyClearDifferencesReal(t *testing.T) {
+	before := reportFor([]int{3, 0, 2, 1}, 3, 0)
+	after := reportFor([]int{3, 3, 0, 1}, 3, 0)
+	c, err := CompareRepeat(before, after)
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := map[string]string{"a": "same", "b": "better", "c": "same", "d": "same"}
+	for _, l := range c.Labels {
+		if l.Verdict != want[l.CaseID] {
+			t.Errorf("%s: %d/%d -> %d/%d verdict %s (p=%.2f), want %s", l.CaseID, l.BeforeCaught, l.BeforeRuns, l.AfterCaught, l.AfterRuns, l.Verdict, l.P, want[l.CaseID])
+		}
+	}
+	if c.Improved != 1 || c.Regressed != 0 || c.Same != 3 {
+		t.Fatalf("%+v", c)
+	}
+}
+
+func TestCompareRepeatPooledAndRegression(t *testing.T) {
+	before := reportFor([]int{3, 3, 3, 3, 3, 3}, 3, 0)
+	after := reportFor([]int{0, 1, 0, 1, 0, 1}, 3, 0)
+	c, err := CompareRepeat(before, after)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if c.PooledVerdict != "worse" || c.Regressed < 1 {
+		t.Fatalf("pooled=%s regressed=%d", c.PooledVerdict, c.Regressed)
+	}
+	md := c.Markdown()
+	for _, want := range []string{"Overall: worse", "clearly worse", "Fisher"} {
+		if !strings.Contains(md, want) {
+			t.Fatalf("markdown lacks %q:\n%s", want, md)
+		}
+	}
+}
+
+func TestCompareRepeatSkipsUnscoredLabelsAndRejectsMismatches(t *testing.T) {
+	before := reportFor([]int{3, 3}, 3, 0)
+	after := reportFor([]int{3, 3}, 3, 0)
+	after.Cases[1].Runs = 0 // every run failed
+	c, err := CompareRepeat(before, after)
+	if err != nil || len(c.Labels) != 1 {
+		t.Fatalf("labels=%d err=%v", len(c.Labels), err)
+	}
+	if _, err := CompareRepeat(reportFor([]int{1}, 3, 0), reportFor([]int{1, 1}, 3, 0)); err == nil {
+		t.Fatal("different datasets must be rejected")
+	}
+	renamed := reportFor([]int{1}, 3, 0)
+	renamed.Cases[0].ID = "other"
+	if _, err := CompareRepeat(reportFor([]int{1}, 3, 0), renamed); err == nil {
+		t.Fatal("different case IDs must be rejected")
+	}
+}
+
+func TestComparisonWarnsWhenCleanNoiseRises(t *testing.T) {
+	c, _ := CompareRepeat(reportFor([]int{1}, 3, 0), reportFor([]int{3}, 3, 1.5))
+	if !strings.Contains(c.Markdown(), "more false alarms") {
+		t.Fatal(c.Markdown())
+	}
+}

